import "server-only";
import { createHmac, timingSafeEqual } from "crypto";
import { getConfigEncryptionSecret } from "@/lib/crypto";

function signature(eventId: string, value: string) {
  return createHmac("sha256", getConfigEncryptionSecret())
    .update(JSON.stringify(["event-url-code:v1", eventId, value]))
    .digest();
}

// A preview is not a reservation. This proof only establishes that the code
// was generated by the server, rather than a host choosing a guessable name.
export function signUrlCode(eventId: string, code: string): string {
  const value = `${Date.now() + 15 * 60 * 1000}.${code}`;
  return `${value}.${signature(eventId, value).toString("hex")}`;
}

export function readUrlCode(eventId: string, proof?: string): string | null {
  if (!proof) return null;
  const match = /^(\d{13})\.([A-Za-z0-9]{6,12})\.([a-f0-9]{64})$/.exec(proof);
  if (!match || Number(match[1]) <= Date.now()) return null;
  const value = `${match[1]}.${match[2]}`;
  return timingSafeEqual(signature(eventId, value), Buffer.from(match[3], "hex")) ? match[2] : null;
}
